	protected static function doOnDeleteCascade(Criteria $criteria, PropelPDO $con)
	{
		// initialize var to track total num of affected rows
		$affectedRows = 0;

		// first find the objects that are implicated by the $criteria
		$objects = Tbrh017TpNominaPeer::doSelect($criteria, $con);
		foreach ($objects as $obj) {


			// delete related Tbrh013Nomina objects
			$c = new Criteria(Tbrh013NominaPeer::DATABASE_NAME);
			
			$c->add(Tbrh013NominaPeer::CO_TP_NOMINA, $obj->getCoTpNomina());
			$affectedRows += Tbrh013NominaPeer::doDelete($c, $con);
		}
		return $affectedRows;
	}

